#!/bin/sh
# Installs {{ app }} {{ version }} from {{ repository_url }}.
# Generated by ag-release {{ ag_release_version }}.
#
# Environment variables:
#   {{ variable_prefix }}_DOWNLOAD_URL: base URL of the release archives.
#   {{ variable_prefix }}_INSTALL_DIR: install prefix; binaries go to its `bin` directory.
#   {{ variable_prefix }}_UNMANAGED_INSTALL: directory to install the binaries into
#     directly, without a receipt or PATH changes.
#   {{ variable_prefix }}_NO_MODIFY_PATH: `1` leaves PATH and shell startup files unchanged.
#
# Every command runs inside `main`, which the last line calls, so a truncated
# download runs nothing.

APP_NAME={{ app_name }}
APP_VERSION={{ app_version }}
DEFAULT_DOWNLOAD_URL={{ download_url }}
SUPPORTED_TARGETS={{ supported_targets }}
{%- if let Some(glibc) = min_glibc %}
MIN_GLIBC={{ glibc }}
MIN_GLIBC_MAJOR={{ glibc.major }}
MIN_GLIBC_MINOR={{ glibc.minor }}
{%- else %}
MIN_GLIBC=
MIN_GLIBC_MAJOR=
MIN_GLIBC_MINOR=
{%- endif %}
RECEIPT_BINARIES={{ receipt_binaries }}
RECEIPT_PROVIDER={{ receipt_provider }}
RECEIPT_SOURCE={{ receipt_source }}
RECEIPT_VERSION={{ receipt_version }}

main() {
    set -u
    _download_base={{ "${" }}{{ variable_prefix }}_DOWNLOAD_URL:-$DEFAULT_DOWNLOAD_URL}
    _install_dir={{ "${" }}{{ variable_prefix }}_INSTALL_DIR:-}
    _unmanaged_dir={{ "${" }}{{ variable_prefix }}_UNMANAGED_INSTALL:-}
    _no_modify_path={{ "${" }}{{ variable_prefix }}_NO_MODIFY_PATH:-0}
    _work_dir=
    _staged=
    trap cleanup EXIT
    trap 'exit 1' HUP INT TERM

    detect_target
    _work_dir=$(mktemp -d) || fail "cannot create a temporary directory"
    say "downloading $APP_NAME $APP_VERSION for $_target"
    download "${_download_base%/}/$_archive" "$_work_dir/$_archive"
    verify_sha256 "$_work_dir/$_archive"
    tar -xzf "$_work_dir/$_archive" -C "$_work_dir" || fail "cannot extract $_archive"

    if [ -n "$_unmanaged_dir" ]; then
        absolute_directory "$_unmanaged_dir"
        install_binaries "$_work_dir/$_directory" "$_absolute"
        say "installed $APP_NAME $APP_VERSION to $_absolute"

        return 0
    fi

    [ -n "${HOME:-}" ] || fail "HOME is not set"
    absolute_directory "${_install_dir:-${CARGO_HOME:-$HOME/.cargo}}"
    _prefix=$_absolute
    absolute_directory "$_prefix/bin"
    _bin_dir=$_absolute
    install_binaries "$_work_dir/$_directory" "$_bin_dir"
    if [ "$_no_modify_path" = 0 ]; then
        _modify_path=true
    else
        _modify_path=false
    fi
    write_receipt
    say "installed $APP_NAME $APP_VERSION to $_bin_dir"
    if [ "$_modify_path" = true ]; then
        update_path
    fi
}

say() {
    printf '%s\n' "$*"
}

fail() {
    printf 'error: %s\n' "$*" >&2
    exit 1
}

cleanup() {
    if [ -n "$_staged" ]; then
        rm -f "$_staged"
    fi
    if [ -n "$_work_dir" ]; then
        rm -rf "$_work_dir"
    fi
}

# Sets `_target` and its `_archive`, `_directory`, and `_sha256`.
detect_target() {
    _system=$(uname -s) || fail "cannot run uname"
    _machine=$(uname -m) || fail "cannot run uname"
    _machines=$_machine
    # Under Rosetta 2, uname reports x86_64 on Apple silicon: prefer the
    # native archive.
    if [ "$_system" = Darwin ] && [ "$_machine" = x86_64 ] &&
        [ "$(sysctl -n hw.optional.arm64 2>/dev/null)" = 1 ]; then
        _machines="arm64 x86_64"
    fi
    _target=
    for _candidate in $_machines; do
        case "$_system $_candidate" in
{%- for arm in targets %}
            {{ arm.patterns }})
                _target={{ arm.target }}
                _archive={{ arm.archive }}
                _directory={{ arm.directory }}
                _sha256={{ arm.sha256 }}
                _glibc={{ arm.glibc }}
                ;;
{%- endfor %}
            *)
                continue
                ;;
        esac
        break
    done
    if [ -z "$_target" ]; then
        fail "unsupported platform $_system $_machine; $APP_NAME supports $SUPPORTED_TARGETS"
    fi
    if [ "$_glibc" = true ]; then
        check_libc
    fi
}

check_libc() {
    _ldd=$(ldd --version 2>&1)
    case "$_ldd" in
        *musl*)
            fail "unsupported platform $_system $_machine with musl libc;" \
                "$APP_NAME supports $SUPPORTED_TARGETS"
            ;;
    esac
    if [ -z "$MIN_GLIBC" ]; then
        return 0
    fi
    # The first line of `ldd --version` ends with the glibc version.
    _glibc_version=$(printf '%s\n' "$_ldd" | awk 'NR == 1 { print $NF }')
    _glibc_major=${_glibc_version%%.*}
    _glibc_minor=${_glibc_version#*.}
    _glibc_minor=${_glibc_minor%%.*}
    case "$_glibc_version" in
        *.*) ;;
        *) _glibc_major= ;;
    esac
    if ! is_number "$_glibc_major" || ! is_number "$_glibc_minor"; then
        fail "cannot determine the glibc version; $APP_NAME needs glibc $MIN_GLIBC or newer"
    fi
    if [ "$_glibc_major" -lt "$MIN_GLIBC_MAJOR" ] || {
        [ "$_glibc_major" -eq "$MIN_GLIBC_MAJOR" ] && [ "$_glibc_minor" -lt "$MIN_GLIBC_MINOR" ]
    }; then
        fail "$APP_NAME needs glibc $MIN_GLIBC or newer, but this system has glibc $_glibc_version"
    fi
}

is_number() {
    case "$1" in
        '' | *[!0-9]*) return 1 ;;
    esac
}

download() {
    if command -v curl >/dev/null 2>&1; then
        curl --fail --location --silent --show-error --output "$2" "$1" ||
            fail "cannot download $1"
    elif command -v wget >/dev/null 2>&1; then
        wget -q -O "$2" "$1" || fail "cannot download $1"
    else
        fail "installing $APP_NAME needs curl or wget"
    fi
}

# Fails unless the file `$1` has the SHA-256 the release recorded.
verify_sha256() {
    if command -v sha256sum >/dev/null 2>&1; then
        _sum=$(sha256sum "$1") || fail "cannot compute the SHA-256 of $_archive"
    elif command -v shasum >/dev/null 2>&1; then
        _sum=$(shasum -a 256 "$1") || fail "cannot compute the SHA-256 of $_archive"
    else
        fail "cannot verify $_archive: neither sha256sum nor shasum is installed"
    fi
    _sum=${_sum%% *}
    if [ "$_sum" != "$_sha256" ]; then
        fail "checksum mismatch for $_archive: expected $_sha256, found $_sum"
    fi
}

# Creates the directory `$1` and sets `_absolute` to its absolute path.
absolute_directory() {
    mkdir -p "$1" || fail "cannot create $1"
    _absolute=$(CDPATH='' cd -- "$1" && pwd) || fail "cannot enter $1"
}

# Moves each binary from `$1` into `$2` with an atomic rename, so a running
# binary is never written over.
install_binaries() {
    for _binary in {{ binaries }}; do
        _staged=$(mktemp "$2/.$_binary.XXXXXX") ||
            fail "cannot create a temporary file in $2"
        if ! cp "$1/$_binary" "$_staged" || ! chmod 755 "$_staged" ||
            ! mv -f "$_staged" "$2/$_binary"; then
            fail "cannot install $2/$_binary"
        fi
        _staged=
        say "  $2/$_binary"
    done
}

write_receipt() {
    _receipt_dir=${XDG_CONFIG_HOME:-$HOME/.config}/$APP_NAME
    mkdir -p "$_receipt_dir" || fail "cannot create $_receipt_dir"
    _json_prefix=$(printf '%s' "$_prefix" | sed 's/\\/\\\\/g; s/"/\\"/g')
    printf \
        '{"binaries":%s,"install_layout":"cargo-home","install_prefix":"%s","modify_path":%s,"provider":%s,"source":%s,"version":%s}\n' \
        "$RECEIPT_BINARIES" "$_json_prefix" "$_modify_path" "$RECEIPT_PROVIDER" \
        "$RECEIPT_SOURCE" "$RECEIPT_VERSION" >"$_receipt_dir/$APP_NAME-receipt.json" ||
        fail "cannot write $_receipt_dir/$APP_NAME-receipt.json"
}

# Puts `_bin_dir` on PATH through `<prefix>/env` and `<prefix>/env.fish`,
# sourced from the shell startup files, unless it is on PATH already.
update_path() {
    case ":${PATH:-}:" in
        *":$_bin_dir:"*) return 0 ;;
    esac
    _env_script=$_prefix/env
    _bin_expression=$(home_expression "$_bin_dir")
    _env_expression=$(home_expression "$_env_script")
    if [ ! -f "$_env_script" ]; then
        write_env_script
    fi
    if [ ! -f "$_env_script.fish" ]; then
        write_fish_env_script
    fi
    _sh_line=". \"$_env_expression\""
    _sh_alternative="source \"$_env_expression\""
    add_line "$HOME/.profile" "$_sh_line" "$_sh_alternative"
    for _rc_file in .bashrc .bash_profile .bash_login; do
        if [ -f "$HOME/$_rc_file" ]; then
            add_line "$HOME/$_rc_file" "$_sh_line" "$_sh_alternative"
        fi
    done
    _zsh_dir=${ZDOTDIR:-$HOME}
    _zsh_rc=$_zsh_dir/.zshrc
    if [ ! -f "$_zsh_rc" ] && [ -f "$_zsh_dir/.zshenv" ]; then
        _zsh_rc=$_zsh_dir/.zshenv
    fi
    add_line "$_zsh_rc" "$_sh_line" "$_sh_alternative"
    _fish_dir=${XDG_CONFIG_HOME:-$HOME/.config}/fish/conf.d
    mkdir -p "$_fish_dir" || fail "cannot create $_fish_dir"
    add_line "$_fish_dir/$APP_NAME.env.fish" "source \"$_env_expression.fish\"" \
        ". \"$_env_expression.fish\""
    if [ -n "${GITHUB_PATH:-}" ]; then
        printf '%s\n' "$_bin_dir" >>"$GITHUB_PATH" || fail "cannot update $GITHUB_PATH"
        say "  added $_bin_dir to $GITHUB_PATH"
    fi
    say ""
    say "To add $_bin_expression to PATH, restart your shell or run:"
    say ""
    say "    $_sh_alternative (sh, bash, zsh)"
    say "    source \"$_env_expression.fish\" (fish)"
}

# Prints `$1` with a leading `$HOME/` in place of the home directory.
home_expression() {
    case "$1" in
        "$HOME"/*)
            # shellcheck disable=SC2016
            printf '$HOME/%s\n' "${1#"$HOME"/}"
            ;;
        *) printf '%s\n' "$1" ;;
    esac
}

write_env_script() {
    cat >"$_env_script" <<EOF || fail "cannot write $_env_script"
#!/bin/sh
# add binaries to PATH if they aren't added yet
# affix colons on either side of \$PATH to simplify matching
case ":\${PATH}:" in
    *:"$_bin_expression":*)
        ;;
    *)
        # Prepending path in case a system-installed binary needs to be overridden
        export PATH="$_bin_expression:\$PATH"
        ;;
esac
EOF
    say "  created $_env_script"
}

write_fish_env_script() {
    cat >"$_env_script.fish" <<EOF || fail "cannot write $_env_script.fish"
if not contains "$_bin_expression" \$PATH
    # Prepending path in case a system-installed binary needs to be overridden
    set -x PATH "$_bin_expression" \$PATH
end
EOF
    say "  created $_env_script.fish"
}

# Appends the line `$2` to the file `$1` unless it holds `$2` or `$3`.
add_line() {
    if grep -qF -- "$2" "$1" 2>/dev/null || grep -qF -- "$3" "$1" 2>/dev/null; then
        return 0
    fi
    printf '\n%s\n' "$2" >>"$1" || fail "cannot update $1"
    say "  updated $1"
}

main "$@"
